title:
// 런너 — Promise가 끝나면 자동으로 next() 호출
function run(generator) {
    const gen = generator();

    function step(value) {
        const result = gen.next(value);
        if (result.done) return;
        result.value.then(step); // Promise 끝나면 next() 자동 호출
    }

    step();
}

